    }
    if (actionId === 'add-after-gap') {
      treeNodeActionsDialog.close();
      if (barrier.kind === 'lineage-gap') {
        treeGeneratorController.openAtLineage(context.partnershipId || state.family.lineage.founderPartnershipId);
