import { resolvePortraitSource } from '../../config/portrait-placeholders.js';
import { escapeHtml, initials } from '../../ui/dom.js';
import { renderBiographyPage } from '../biography-page/biography-page-renderer.js';
import { sanitizeBiographyImageSource } from './person-biography-content.js';
import { normalizePersonBiographyModule } from './person-biography-model.js';

function biographyPortrait(person, data) {
  const mainPortrait = sanitizeBiographyImageSource(data.portrait) || sanitizeBiographyImageSource(resolvePortraitSource(person));
  const stages = (Array.isArray(data.portraitStages) ? data.portraitStages : [])
    .map((source, index) => ({
      label: `[${index + 2}]`,
      image: sanitizeBiographyImageSource(source)
    }))
    .filter(stage => stage.image);

  if (!stages.length) {
    return mainPortrait
      ? `<img class="biography-portrait" src="${escapeHtml(mainPortrait)}" alt="Portrait von ${escapeHtml(person.name)}" loading="lazy" decoding="async">`
      : `<div class="biography-portrait placeholder" role="img" aria-label="Kein Portrait vorhanden">${escapeHtml(initials(person.name))}</div>`;
  }

  const portraits = [{ label: '[1]', image: mainPortrait }, ...stages];
  return `<div class="person-biography-portrait-tabs" data-biography-portrait-tabs>
    <div class="person-biography-portrait-tab-bar" role="tablist" aria-label="Portrait-Altersstufen">
      ${portraits.map((portrait, index) => `<button class="person-biography-portrait-tab${index === 0 ? ' is-active' : ''}" type="button" role="tab" aria-selected="${index === 0 ? 'true' : 'false'}" data-biography-portrait-tab="${index}">${escapeHtml(portrait.label)}</button>`).join('')}
    </div>
    ${portraits.map((portrait, index) => portrait.image
      ? `<img class="biography-portrait person-biography-portrait-pane${index === 0 ? ' is-active' : ''}" data-biography-portrait-pane="${index}" src="${escapeHtml(portrait.image)}" alt="${escapeHtml(portrait.label)} · Portrait von ${escapeHtml(person.name)}" loading="${index === 0 ? 'eager' : 'lazy'}" decoding="async">`
      : `<div class="biography-portrait person-biography-portrait-pane placeholder${index === 0 ? ' is-active' : ''}" data-biography-portrait-pane="${index}" role="img" aria-label="Kein Portrait vorhanden">${escapeHtml(initials(person.name))}</div>`).join('')}
  </div>`;
}

export function renderPersonBiography({ person, biographyModule, documentRef = globalThis.document }) {
  const module = normalizePersonBiographyModule(biographyModule);
  return renderBiographyPage({
    portraitHtml: biographyPortrait(person, module.biography),
    stats: module.stats,
    quote: module.quote,
    quoteBy: module.quoteBy,
    data: module.biography,
    documentRef
  });
}

import { escapeHtml } from '../../ui/dom.js';

const MAX_DATA_IMAGE_LENGTH = 800000;
const DATA_IMAGE_PATTERN = /^data:image\/(?:png|jpe?g|gif|webp);base64,[a-z0-9+/=\s]+$/i;

function isSafeHttpUrl(value) {
  try {
    const url = new URL(value, 'https://aleria.invalid/');
    return url.protocol === 'http:' || url.protocol === 'https:';
  } catch {
    return false;
  }
}

function isSafeRelativeUrl(value) {
  return !/^[a-z][a-z0-9+.-]*:/i.test(value)
    && !/^\/\//.test(value)
    && !/[\\\r\n]/.test(value);
}

export function sanitizeBiographyImageSource(source) {
  const value = String(source || '').trim();
  if (!value) return '';
  if (/^data:/i.test(value)) {
    if (value.length > MAX_DATA_IMAGE_LENGTH || !DATA_IMAGE_PATTERN.test(value)) return '';
    return value.replace(/\s+/g, '');
  }
  if (/^https?:\/\//i.test(value)) return isSafeHttpUrl(value) ? value : '';
  return isSafeRelativeUrl(value) ? value : '';
}

export function sanitizeBiographyHref(source) {
  const value = String(source || '').trim();
  if (!value || /^(?:javascript|data|vbscript):/i.test(value)) return '';
  if (/^https?:\/\//i.test(value)) return isSafeHttpUrl(value) ? value : '';
  return isSafeRelativeUrl(value) ? value : '';
}

export function sanitizeBiographyRichText(value, documentRef = globalThis.document) {
  if (!documentRef?.createElement) return escapeHtml(value).replace(/\r?\n/g, '<br>');

  const template = documentRef.createElement('template');
  template.innerHTML = String(value || '');
  // Absatzcontainer aus eingefügtem Word-/Rich-Text-Inhalt bleiben erhalten. Ihre
  // Attribute werden unten ebenso vollständig entfernt wie bei den anderen erlaubten
  // Elementen; dadurch gehen weder Absatzgrenzen noch verschachtelte Hervorhebungen verloren.
  const allowedTags = new Set(['BR', 'P', 'DIV', 'STRONG', 'EM', 'B', 'I', 'U', 'A', 'SPAN']);
  Array.from(template.content.querySelectorAll('*')).forEach(element => {
    if (!allowedTags.has(element.tagName)) {
      element.replaceWith(documentRef.createTextNode(element.textContent || ''));
      return;
    }

    if (element.tagName === 'A') {
      const href = sanitizeBiographyHref(element.getAttribute('href'));
      const text = element.textContent || '';
      Array.from(element.attributes).forEach(attribute => element.removeAttribute(attribute.name));
      if (!href) {
        element.replaceWith(documentRef.createTextNode(text));
        return;
      }
      element.setAttribute('href', href);
      if (/^https?:\/\//i.test(href)) {
        element.setAttribute('target', '_blank');
        element.setAttribute('rel', 'noopener noreferrer');
      }
      return;
    }

    if (element.tagName === 'SPAN') {
      const tip = String(element.getAttribute('data-tip') || '').trim().slice(0, 300);
      const isTooltip = element.classList.contains('module-tooltip');
      const isTooltipLabel = element.classList.contains('module-tooltip-label');
      const isTooltipPopover = element.classList.contains('module-tooltip-popover');
      const spoiler = element.getAttribute('data-spoiler') === 'true'
        || element.classList.contains('module-spoiler')
        || element.classList.contains('editor-spoiler');
      const label = element.textContent || '';
      Array.from(element.attributes).forEach(attribute => element.removeAttribute(attribute.name));
      if (isTooltip) {
        element.className = 'module-tooltip';
        element.setAttribute('tabindex', '0');
        return;
      }
      if (isTooltipLabel) {
        element.className = 'module-tooltip-label';
        return;
      }
      if (isTooltipPopover) {
        element.className = 'module-tooltip-popover';
        return;
      }
      if (tip) {
        element.className = 'module-tooltip';
        element.setAttribute('tabindex', '0');
        element.textContent = '';
        const labelElement = documentRef.createElement('span');
        labelElement.className = 'module-tooltip-label';
        labelElement.textContent = label || 'Text';
        const popover = documentRef.createElement('span');
        popover.className = 'module-tooltip-popover';
        popover.textContent = tip;
        element.append(labelElement, popover);
        return;
      }
      if (spoiler) {
        element.className = 'module-spoiler';
        element.setAttribute('data-spoiler', 'true');
        return;
      }
      element.replaceWith(documentRef.createTextNode(label));
      return;
    }

    Array.from(element.attributes).forEach(attribute => element.removeAttribute(attribute.name));
  });
  return template.innerHTML.replace(/\n/g, '<br>');
}

import { formatAge } from '../../domain/person-presentation.js';

export const PERSON_BIOGRAPHY_EXTENSION_ID = 'biographyModule';
export const PERSON_BIOGRAPHY_SCHEMA = 'aleria.biography-module';
export const PERSON_BIOGRAPHY_SCHEMA_VERSION = 1;

function clampNumber(value, fallback, minimum, maximum) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(minimum, Math.min(maximum, Math.round(parsed)));
}

function normalizeLineArray(value) {
  return Array.isArray(value)
    ? value.map(item => String(item || '').trim()).filter(Boolean)
    : [];
}

function normalizePortraitStages(value) {
  const stages = Array.isArray(value) ? value : [];
  return Array.from({ length: 4 }, (_, index) => String(stages[index] || '').trim());
}

function normalizePairArray(value) {
  return Array.isArray(value)
    ? value.map(item => ({
        title: String(item?.title || '').trim(),
        detail: String(item?.detail || '').trim(),
        icon: String(item?.icon || '').trim()
      })).filter(item => item.title || item.detail || item.icon)
    : [];
}

function normalizeSections(value) {
  return Array.isArray(value)
    ? value.map(item => ({
        position: item?.position === 'afterWorks' ? 'afterWorks' : 'afterIntro',
        mode: item?.mode === 'list' ? 'list' : 'text',
        title: String(item?.title || '').trim(),
        text: String(item?.text || item?.body || '').trim()
      })).filter(item => item.title || item.text).slice(0, 16)
    : [];
}

function normalizeConnectionFormat(value) {
  return ['portrait', 'landscape', 'square'].includes(value) ? value : 'portrait';
}

function normalizeConnections(value) {
  return Array.isArray(value)
    ? value.map(item => {
        if (item?.type === 'heading') {
          return {
            type: 'heading',
            title: String(item.title || item.name || '').trim(),
            detail: String(item.detail || item.text || '').trim()
          };
        }
        return {
          type: 'connection',
          name: String(item?.name || '').trim(),
          detail: String(item?.detail || '').trim(),
          image: String(item?.image || '').trim(),
          imageFormat: normalizeConnectionFormat(item?.imageFormat)
        };
      }).filter(item => item.type === 'heading'
        ? item.title || item.detail
        : item.name || item.detail || item.image)
    : [];
}

function normalizeDocuments(value) {
  return Array.isArray(value)
    ? value.map(item => {
        if (typeof item === 'string') return { icon: '', title: '', text: item.trim(), link: '' };
        return {
          icon: String(item?.icon || item?.image || '').trim(),
          title: String(item?.title || item?.name || '').trim(),
          text: String(item?.text || '').trim(),
          link: String(item?.link || item?.url || item?.href || '').trim()
        };
      }).filter(item => item.icon || item.title || item.text || item.link)
    : [];
}

export function normalizeBiographyData(data = {}) {
  return {
    portrait: String(data.portrait || '').trim(),
    portraitStages: normalizePortraitStages(data.portraitStages),
    sideWidth: clampNumber(data.sideWidth, 100, 35, 100),
    connectionPortraitHeight: clampNumber(data.connectionPortraitHeight, 68, 44, 140),
    connectionTextOffset: clampNumber(data.connectionTextOffset, 0, 0, 80),
    biographyTitle: String(data.biographyTitle || 'Biografie').trim(),
    biographyText: String(data.biographyText || '').trim(),
    abilitiesTitle: String(data.abilitiesTitle || 'Persönlichkeit').trim(),
    abilities: normalizePairArray(data.abilities),
    extraSections: normalizeSections(data.extraSections),
    historyTitle: String(data.historyTitle || 'Hintergrund').trim(),
    historyText: String(data.historyText || '').trim(),
    worksTitle: String(data.worksTitle || 'Bekannte Werke').trim(),
    works: normalizeLineArray(data.works),
    triviaTitle: String(data.triviaTitle || 'Trivia').trim(),
    trivia: normalizeLineArray(data.trivia),
    quotesTitle: String(data.quotesTitle || 'Zitate').trim(),
    quotes: normalizeLineArray(data.quotes),
    connectionsTitle: String(data.connectionsTitle || 'Verbindungen').trim(),
    connections: normalizeConnections(data.connections),
    documentsTitle: String(data.documentsTitle || 'Eigentum & Besitz').trim(),
    documents: normalizeDocuments(data.documents),
    footer: String(data.footer || '').trim()
  };
}

function normalizeStats(value) {
  return Array.isArray(value)
    ? value.map(item => (
        Array.isArray(item)
          ? [String(item[0] || '').trim(), String(item[1] || '').trim()]
          : [String(item?.label || '').trim(), String(item?.value || '').trim()]
      )).filter(([label, entry]) => label || entry)
    : [];
}

export function normalizePersonBiographyModule(value = {}) {
  return {
    schema: PERSON_BIOGRAPHY_SCHEMA,
    schemaVersion: PERSON_BIOGRAPHY_SCHEMA_VERSION,
    stats: normalizeStats(value.stats),
    quote: String(value.quote || '').trim(),
    quoteBy: String(value.quoteBy || '').trim(),
    biography: normalizeBiographyData(value.biography || value)
  };
}

// Firestore lehnt Arrays ab, die direkt weitere Arrays enthalten ("Nested arrays are not
// supported"). normalizeStats() haelt die Infotabelle intern als [label, wert]-Paare - praktisch
// fuer Rendering/Editor, aber ein Array von Arrays und deshalb nicht Firestore-tauglich. Vor jedem
// Schreibvorgang (privater Entwurf wie Veroeffentlichung) muessen die Zeilen deshalb in
// {label, value}-Objekte gewandelt werden; normalizeStats() liest beide Formen bereits wieder ein.
export function sanitizeBiographyStatsForFirestore(stats) {
  return Array.isArray(stats)
    ? stats.map(item => (Array.isArray(item)
        ? { label: String(item[0] ?? ''), value: String(item[1] ?? '') }
        : item))
    : [];
}

export function getPersonBiographyModule(person) {
  const stored = person?.extensions?.[PERSON_BIOGRAPHY_EXTENSION_ID];
  return stored && typeof stored === 'object'
    ? normalizePersonBiographyModule(stored)
    : null;
}

export function createPersonBiographyStats(person = {}, house = null) {
  const sex = person.sex === 'female' ? 'Weiblich' : person.sex === 'male' ? 'Männlich' : 'Unbekannt';
  const death = person.death
    || (person.status === 'alive' ? 'Lebend' : person.status === 'missing' ? 'Verschollen' : 'Unbekannt');
  return [
    ['Vollständiger Name', person.name || ''],
    ['Haus', house?.name || ''],
    ['Titel / Anrede', person.title || ''],
    ['Geboren', person.birth || ''],
    ['Geburtsort', ''],
    ['Gestorben', death],
    ['Alter im Jahr 1740', formatAge(person)],
    ['Geschlecht', sex],
    ['Familienstand', ''],
    ['Rang / Stand', ''],
    ['Tätigkeit', ''],
    ['Wohnsitz', '']
  ];
}

export function createPersonBiographyModule(person, house = null) {
  return normalizePersonBiographyModule({
    stats: createPersonBiographyStats(person, house),
    biography: {
      footer: person?.name ? `Personenakte · ${person.name}` : 'Personenakte'
    }
  });
}
